```python
from fastmcp import FastMCP

math_server = FastMCP(name="MathServer")


@math_server.tool
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b


@math_server.tool
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b


main_server = FastMCP(name="MainServer")
main_server.mount(math_server, namespace="math")


if __name__ == "__main__":
    main_server.run()
